UPDATE g_exam
USER_ID = #{userId}, EXAM_CODE = #{examCode}, EXAM_NAME = #{examName}, SUBJECT_TYPE = #{subjectType}, EXAM_LV = #{examLv}, EXAM_TIME = #{examTime}, GRA = #{gra},
WHERE EXAM_ID = #{examId}

mapper.select:
SELECT e.EXAM_ID, e.USER_ID, e.EXAM_CODE, e.EXAM_NAME, e.SUBJECT_TYPE, e.EXAM_LV, e.EXAM_TIME, e.GRA, u.USER_NAME, u.NAME, sub.CODE_DESC as SUBJECT_TYPE_DESC, el.CODE_DESC as EXAM_LV_DESC FROM g_exam e LEFT JOIN g_user u ON e.USER_ID = u.USER_ID LEFT JOIN g_code sub ON e.SUBJECT_TYPE = sub.CODE_ID LEFT JOIN g_code el ON e.EXAM_LV = el.CODE_ID WHERE e.GRA = #{grade} AND e.SUBJECT_TYPE IN
#{subject}
ORDER BY e.EXAM_TIME DESC
